window.M3_BANK = {"meta": {"count": 60, "topics": {"3.01": {"en": "Electron theory", "el": "Θεωρία ηλεκτρονίων"}, "3.02": {"en": "Static electricity and conduction", "el": "Στατικός ηλεκτρισμός και αγωγή"}, "3.03": {"en": "Electrical terminology", "el": "Ηλεκτρική ορολογία"}, "3.04": {"en": "Generation of electricity", "el": "Παραγωγή ηλεκτρισμού"}, "3.05": {"en": "DC sources of electricity", "el": "Πηγές DC"}, "3.06": {"en": "DC circuits", "el": "Κυκλώματα DC"}, "3.07": {"en": "Resistance / resistor", "el": "Αντίσταση / αντιστάτης"}, "3.08": {"en": "Power", "el": "Ισχύς"}, "3.09": {"en": "Capacitance / capacitor", "el": "Χωρητικότητα / πυκνωτής"}, "3.10": {"en": "Magnetism", "el": "Μαγνητισμός"}, "3.11": {"en": "Inductance / inductor", "el": "Αυτεπαγωγή / πηνίο"}, "3.12": {"en": "DC motor / generator theory", "el": "Κινητήρες και γεννήτριες DC"}, "3.13": {"en": "AC theory", "el": "Θεωρία AC"}, "3.14": {"en": "R, C and L circuits", "el": "Κυκλώματα R, C, L"}, "3.15": {"en": "Transformers", "el": "Μετασχηματιστές"}, "3.16": {"en": "Filters", "el": "Φίλτρα"}, "3.17": {"en": "AC generators", "el": "Γεννήτριες AC"}, "3.18": {"en": "AC motors", "el": "Κινητήρες AC"}}, "exam": {"options": 3, "pass_mark": 0.75}}, "misc": {"octet_mixup": {"en": "8 is the limit of the second shell. Use 2n² with n = 3.", "el": "Το 8 είναι το όριο της δεύτερης στιβάδας. Χρησιμοποίησε 2n² με n = 3."}, "wrong_n": {"en": "Check which shell: n = 1, 2, 3 … then apply 2n².", "el": "Έλεγξε ποια στιβάδα: n = 1, 2, 3 … και μετά 2n²."}, "forgot_square": {"en": "The n is squared: 2n², not 2n.", "el": "Το n είναι στο τετράγωνο: 2n², όχι 2n."}, "ion_sign": {"en": "Losing negative electrons makes the atom positive (cation); gaining them makes it negative (anion).", "el": "Χάνοντας αρνητικά ηλεκτρόνια το άτομο γίνεται θετικό (κατιόν)· κερδίζοντας γίνεται αρνητικό (ανιόν)."}, "isotope_mixup": {"en": "Isotopes differ in neutrons, not electrons.", "el": "Τα ισότοπα διαφέρουν στα νετρόνια, όχι στα ηλεκτρόνια."}, "neutral_mixup": {"en": "A neutral atom has equal numbers of protons and electrons.", "el": "Ουδέτερο άτομο: ίσος αριθμός πρωτονίων και ηλεκτρονίων."}, "electron_mass": {"en": "Electrons are about 1/1836 of a proton's mass: they hardly count in the atom's mass.", "el": "Το ηλεκτρόνιο έχει περίπου το 1/1836 της μάζας του πρωτονίου: σχεδόν δεν μετράει στη μάζα του ατόμου."}, "full_shell": {"en": "A full outer shell holds its electrons tightly: that makes an insulator.", "el": "Πλήρης εξωτερική στιβάδα κρατά σφιχτά τα ηλεκτρόνια: αυτό κάνει έναν μονωτή."}, "neutron_mixup": {"en": "Neutrons carry no charge and do not carry current.", "el": "Τα νετρόνια δεν έχουν φορτίο και δεν μεταφέρουν ρεύμα."}, "ion_breakdown": {"en": "Ionization is any gain or loss of electrons; breakdown is the failure of an insulator in a strong field.", "el": "Ιοντισμός είναι κάθε κέρδος ή απώλεια ηλεκτρονίων· διάσπαση είναι η αστοχία μονωτή σε ισχυρό πεδίο."}, "atom_molecule": {"en": "A single atom of hydrogen or oxygen is not water.", "el": "Ένα άτομο υδρογόνου ή οξυγόνου δεν είναι νερό."}, "element_mixup": {"en": "Water is a compound of two elements, not an element.", "el": "Το νερό είναι ένωση δύο στοιχείων, όχι στοιχείο."}, "inner_shell": {"en": "Inner electrons are tightly bound and take no part in bonding.", "el": "Τα εσωτερικά ηλεκτρόνια είναι σφιχτά δεμένα και δεν συμμετέχουν στους δεσμούς."}, "nucleus_mixup": {"en": "There are no electrons in the nucleus: only protons and neutrons.", "el": "Στον πυρήνα δεν υπάρχουν ηλεκτρόνια: μόνο πρωτόνια και νετρόνια."}, "mass_weight": {"en": "kg is mass. Weight is a force, in newtons: W = m × g.", "el": "Τα kg είναι μάζα. Το βάρος είναι δύναμη, σε newton: W = m × g."}, "divided_g": {"en": "Multiply by g, do not divide.", "el": "Πολλαπλασίασε με το g, μη διαιρείς."}, "nucleus_carrier": {"en": "Protons stay inside the nuclei; they are never free carriers here.", "el": "Τα πρωτόνια μένουν μέσα στους πυρήνες· δεν είναι ελεύθεροι φορείς."}, "inverse_g": {"en": "To get mass from weight, divide by g: m = W / g.", "el": "Για μάζα από βάρος, διαίρεσε με g: m = W / g."}, "mass_ratio": {"en": "The ratio is about 1836, not a small number.", "el": "Ο λόγος είναι περίπου 1836, όχι μικρός αριθμός."}, "ion_not_element": {"en": "Changing the electrons makes an ion of the same element; only the protons decide the element.", "el": "Αλλαγή στα ηλεκτρόνια δίνει ιόν του ίδιου στοιχείου· μόνο τα πρωτόνια καθορίζουν το στοιχείο."}, "valence_count": {"en": "6 is only the outer (valence) shell. A neutral atom has as many electrons as protons.", "el": "Το 6 είναι μόνο η εξωτερική στιβάδα. Ουδέτερο άτομο έχει τόσα ηλεκτρόνια όσα πρωτόνια."}, "square_mixup": {"en": "2n² means 2 × n × n, not (2n)² or n²: 2 × 16 = 32.", "el": "2n² σημαίνει 2 × n × n, όχι (2n)² ή n²: 2 × 16 = 32."}, "not_full": {"en": "A shell does not have to be full before the next one starts filling.", "el": "Μια στιβάδα δεν χρειάζεται να γεμίσει πριν αρχίσει να γεμίζει η επόμενη."}, "semi_mixup": {"en": "Silicon and germanium are semiconductors: between conductors and insulators.", "el": "Πυρίτιο και γερμάνιο είναι ημιαγωγοί: ανάμεσα σε αγωγούς και μονωτές."}, "static_dynamic": {"en": "Static means charge at rest on a surface; moving charge is a current (dynamic).", "el": "Στατικός σημαίνει φορτίο σε ηρεμία σε επιφάνεια· το φορτίο που κινείται είναι ρεύμα (δυναμικός)."}, "conductor_leaks": {"en": "A conductor or a ground lets the charge flow away, so it cannot build up.", "el": "Ένας αγωγός ή μια γείωση αφήνουν το φορτίο να φύγει, οπότε δεν συσσωρεύεται."}, "tribo_sign": {"en": "Losing negative electrons leaves a material positive, not negative.", "el": "Όταν ένα υλικό χάνει αρνητικά ηλεκτρόνια μένει θετικό, όχι αρνητικό."}, "conservation": {"en": "Charge is not created: electrons gained by one material were lost by the other.", "el": "Το φορτίο δεν δημιουργείται: τα ηλεκτρόνια που κέρδισε το ένα υλικό τα έχασε το άλλο."}, "like_unlike": {"en": "Same charge from the same rod: like charges repel.", "el": "Ίδιο φορτίο από την ίδια ράβδο: τα όμοια φορτία απωθούνται."}, "charged_force": {"en": "Two charged objects always exert a force on each other.", "el": "Δύο φορτισμένα σώματα ασκούν πάντα δύναμη το ένα στο άλλο."}, "neutral_charged": {"en": "The paper stays neutral overall; its charges only separate (polarization).", "el": "Το χαρτί μένει συνολικά ουδέτερο· τα φορτία του απλώς διαχωρίζονται (πόλωση)."}, "gravity_mixup": {"en": "Gravity pulls down; the upward pull is electric.", "el": "Η βαρύτητα τραβά προς τα κάτω· η έλξη προς τα πάνω είναι ηλεκτρική."}, "test_charge": {"en": "By agreement the test charge is positive, so lines leave + and enter −.", "el": "Συμβατικά το φορτίο δοκιμής είναι θετικό, οπότε οι γραμμές φεύγουν από + και μπαίνουν σε −."}, "lines_cross": {"en": "At each point the field has one direction, so lines can never cross.", "el": "Σε κάθε σημείο το πεδίο έχει μία φορά, άρα οι γραμμές δεν τέμνονται ποτέ."}, "closed_loops": {"en": "Electric field lines start on + and end on −; they do not close on themselves.", "el": "Οι γραμμές του ηλεκτρικού πεδίου ξεκινούν από + και τελειώνουν σε −· δεν κλείνουν."}, "outer_surface": {"en": "Like charges push each other to the outer surface; inside there is no charge and no field.", "el": "Τα όμοια φορτία σπρώχνονται στην εξωτερική επιφάνεια· μέσα δεν υπάρχει φορτίο ούτε πεδίο."}, "sharp_points": {"en": "Charge is not even on an irregular shape: it piles up at points and sharp edges.", "el": "Σε ακανόνιστο σχήμα το φορτίο δεν είναι ομοιόμορφο: μαζεύεται στις αιχμές και τις ακμές."}, "esd_safe": {"en": "Wrist straps and ESD bags protect the component; touching the pins is the danger.", "el": "Το βραχιόλι και οι σακούλες ESD προστατεύουν· ο κίνδυνος είναι να αγγίξεις τις ακίδες."}, "fuel_conductor": {"en": "Fuel is a poor conductor: that is why the charge stays and can spark.", "el": "Το καύσιμο είναι κακός αγωγός: γι' αυτό το φορτίο μένει και μπορεί να δώσει σπινθήρα."}, "fuel_purpose": {"en": "Bonding and grounding are about static charge, not fuel quantity.", "el": "Η σύνδεση και η γείωση αφορούν το στατικό φορτίο, όχι την ποσότητα καυσίμου."}, "forgot_square_d": {"en": "The distance is squared: twice the distance gives ¼ of the force.", "el": "Η απόσταση είναι στο τετράγωνο: διπλάσια απόσταση δίνει το ¼ της δύναμης."}, "inverse_mixup": {"en": "Force grows with the charges and falls with distance, not the other way round.", "el": "Η δύναμη αυξάνεται με τα φορτία και μειώνεται με την απόσταση, όχι ανάποδα."}, "square_charge": {"en": "Only the distance is squared; the charges enter once each.", "el": "Μόνο η απόσταση είναι στο τετράγωνο· τα φορτία μπαίνουν μία φορά το καθένα."}, "inverted": {"en": "Check which quantity goes on top: the formula, not the numbers, decides.", "el": "Έλεγξε ποιο μέγεθος πάει στον αριθμητή: το καθορίζει ο τύπος, όχι οι αριθμοί."}, "divided": {"en": "Here you multiply, not divide.", "el": "Εδώ πολλαπλασιάζουμε, δεν διαιρούμε."}, "multiplied": {"en": "Here you divide, not multiply.", "el": "Εδώ διαιρούμε, δεν πολλαπλασιάζουμε."}, "one_coulomb": {"en": "6.24 × 10¹⁸ is one coulomb; multiply by the number of coulombs.", "el": "Το 6,24 × 10¹⁸ είναι ένα coulomb· πολλαπλασίασε με τον αριθμό των coulomb."}, "contact_induction": {"en": "Contact gives the same sign as the rod; induction gives the opposite sign.", "el": "Η επαφή δίνει το ίδιο πρόσημο με τη ράβδο· η επαγωγή το αντίθετο."}, "ground_order": {"en": "The bar keeps its charge only if the ground is removed before the rod.", "el": "Η ράβδος κρατά το φορτίο μόνο αν αφαιρεθεί η γείωση πριν από τη φορτισμένη ράβδο."}, "metal_liquid": {"en": "Only metals conduct with free electrons; in solutions the carriers are ions.", "el": "Μόνο τα μέταλλα άγουν με ελεύθερα ηλεκτρόνια· στα διαλύματα οι φορείς είναι ιόντα."}, "vacuum_ideal": {"en": "A vacuum has no carriers of its own, so by itself it does not conduct.", "el": "Το κενό δεν έχει δικούς του φορείς, άρα από μόνο του δεν άγει."}, "vacuum_ions": {"en": "A vacuum contains no ions; carriers must be put into it.", "el": "Το κενό δεν περιέχει ιόντα· οι φορείς πρέπει να μπουν απ' έξω."}, "prefix_step": {"en": "Each prefix step is × 1 000. Count the steps between the two units.", "el": "Κάθε βήμα προθέματος είναι × 1 000. Μέτρα τα βήματα ανάμεσα στις δύο μονάδες."}, "prefix_direction": {"en": "Big unit → small unit: multiply. Small → big: divide.", "el": "Από μεγάλη σε μικρή μονάδα: πολλαπλασιάζουμε. Από μικρή σε μεγάλη: διαιρούμε."}, "milli_micro": {"en": "μ → n → p are steps of 1 000 each; 47 nF is not 47 pF.", "el": "μ → n → p είναι βήματα του 1 000· τα 47 nF δεν είναι 47 pF."}, "voltage_current": {"en": "Charge per second is current (I = Q/t); voltage is energy per charge (V = W/Q).", "el": "Φορτίο ανά δευτερόλεπτο είναι το ρεύμα (I = Q/t)· τάση είναι ενέργεια ανά φορτίο (V = W/Q)."}, "resistance_pd": {"en": "Opposition to current is resistance (Ω), not potential difference.", "el": "Η αντίσταση στη ροή είναι η αντίσταση (Ω), όχι η διαφορά δυναμικού."}, "emf_pd": {"en": "The voltage across a lamp is a PD (energy taken); emf is what the source supplies.", "el": "Η τάση σε μια λάμπα είναι πτώση τάσης (ενέργεια που αφαιρείται)· ΗΕΔ είναι ό,τι δίνει η πηγή."}, "absolute_potential": {"en": "Flow depends on the difference between the two points, not on one value alone.", "el": "Η ροή εξαρτάται από τη διαφορά ανάμεσα στα δύο σημεία, όχι από μία τιμή μόνη της."}, "pipe_size": {"en": "The pipe sets how easily water flows, but without a pressure difference there is no flow at all.", "el": "Ο σωλήνας ορίζει πόσο εύκολα ρέει το νερό, αλλά χωρίς διαφορά πίεσης δεν υπάρχει ροή."}, "minutes": {"en": "Convert the time to seconds first: 1 min = 60 s.", "el": "Μετάτρεψε πρώτα τον χρόνο σε δευτερόλεπτα: 1 min = 60 s."}, "billion_mixup": {"en": "10¹⁸ is a billion billions, not a billion (10⁹). Your notes, slide 12, get this wrong.", "el": "Το 10¹⁸ είναι δισεκατομμύριο δισεκατομμύρια, όχι δισεκατομμύριο (10⁹). Οι σημειώσεις (slide 12) το γράφουν λάθος."}, "elementary_charge": {"en": "1.6 × 10⁻¹⁹ C is the charge of one electron, not a number of electrons.", "el": "Το 1,6 × 10⁻¹⁹ C είναι το φορτίο ενός ηλεκτρονίου, όχι πλήθος ηλεκτρονίων."}, "signal_speed": {"en": "Electrons drift at a fraction of a mm/s; it is the push (the field) that travels fast.", "el": "Τα ηλεκτρόνια κινούνται με κλάσματα του mm/s· γρήγορα διαδίδεται η «ώθηση» (το πεδίο)."}, "lamp_store": {"en": "A lamp stores no charge; the electrons already in the wire start moving together.", "el": "Η λάμπα δεν αποθηκεύει φορτίο· τα ηλεκτρόνια που ήδη υπάρχουν στο σύρμα ξεκινούν μαζί."}, "ohm_inverse": {"en": "More resistance means less current, not more.", "el": "Περισσότερη αντίσταση σημαίνει λιγότερο ρεύμα, όχι περισσότερο."}, "ohm_unchanged": {"en": "The current does change: it depends on the voltage and on R (or G).", "el": "Το ρεύμα αλλάζει: εξαρτάται από την τάση και από την R (ή τη G)."}, "G_R_mixup": {"en": "E / I gives the resistance in ohms; conductance is the inverse, I / E, in siemens.", "el": "Το E / I δίνει την αντίσταση σε Ω· η αγωγιμότητα είναι το αντίστροφο, I / E, σε siemens."}, "inverse_G": {"en": "Current is proportional to conductance, not inversely proportional.", "el": "Το ρεύμα είναι ανάλογο της αγωγιμότητας, όχι αντιστρόφως ανάλογο."}, "polarity_sign": {"en": "Extra electrons give a negative charge and negative polarity.", "el": "Επιπλέον ηλεκτρόνια δίνουν αρνητικό φορτίο και αρνητική πολικότητα."}, "sum_charges": {"en": "Coulomb's law multiplies the charges (q₁ × q₂); it does not add them.", "el": "Ο νόμος του Coulomb πολλαπλασιάζει τα φορτία (q₁ × q₂)· δεν τα προσθέτει."}, "flow_direction": {"en": "Conventional current is + → −; electrons move − → +.", "el": "Η συμβατική φορά είναι + → −· τα ηλεκτρόνια κινούνται − → +."}, "flow_only": {"en": "Both conventions work; what matters is not mixing them in the same analysis.", "el": "Και οι δύο συμβάσεις δουλεύουν· σημασία έχει να μην τις ανακατεύεις."}}, "questions": [{"id": "L01-weight-si", "lesson": "L01", "topic": "3.01", "d": 1, "units": "SI", "q": {"en": "A 12 kg battery weighs (g = 9.81 m/s²):", "el": "Μπαταρία 12 kg έχει βάρος (g = 9,81 m/s²):"}, "o": [{"en": "1.22 N", "el": "1,22 N"}, {"en": "12 N", "el": "12 N"}, {"en": "118 N", "el": "118 N"}], "a": 2, "tags": ["divided_g", "mass_weight", null], "x": {"en": "W = m × g = 12 × 9.81 ≈ 118 N.", "el": "W = m × g = 12 × 9,81 ≈ 118 N."}, "status": "new"}, {"id": "L01-weight-imp", "lesson": "L01", "topic": "3.01", "d": 2, "units": "imperial", "q": {"en": "A component of mass 3 slugs weighs (g = 32.2 ft/s²):", "el": "Εξάρτημα μάζας 3 slugs έχει βάρος (g = 32,2 ft/s²):"}, "o": [{"en": "96.6 lbf", "el": "96,6 lbf"}, {"en": "10.7 lbf", "el": "10,7 lbf"}, {"en": "3 lbf", "el": "3 lbf"}], "a": 0, "tags": [null, "divided_g", "mass_weight"], "x": {"en": "W = m × g = 3 slug × 32.2 ft/s² = 96.6 lbf (1 lbf = 1 slug·ft/s²).", "el": "W = m × g = 3 slug × 32,2 ft/s² = 96,6 lbf (1 lbf = 1 slug·ft/s²)."}, "status": "new"}, {"id": "L01-mass-g", "lesson": "L01", "topic": "3.01", "d": 2, "units": "SI", "q": {"en": "An object weighs 49 N on Earth (g = 9.81 m/s²). Its mass is about:", "el": "Ένα σώμα ζυγίζει 49 N στη Γη (g = 9,81 m/s²). Η μάζα του είναι περίπου:"}, "o": [{"en": "481 kg", "el": "481 kg"}, {"en": "5 kg", "el": "5 kg"}, {"en": "49 kg", "el": "49 kg"}], "a": 1, "tags": ["inverse_g", null, "mass_weight"], "x": {"en": "m = W / g = 49 / 9.81 ≈ 5 kg.", "el": "m = W / g = 49 / 9,81 ≈ 5 kg."}, "status": "new"}, {"id": "L01-neutron-charge", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The neutron has:", "el": "Το νετρόνιο έχει:"}, "o": [{"en": "a positive charge", "el": "θετικό φορτίο"}, {"en": "no charge", "el": "μηδενικό φορτίο"}, {"en": "a negative charge", "el": "αρνητικό φορτίο"}], "a": 1, "tags": ["neutron_mixup", null, "neutron_mixup"], "x": {"en": "Neutrons are neutral; the proton is positive and the electron negative.", "el": "Το νετρόνιο είναι ουδέτερο· το πρωτόνιο θετικό, το ηλεκτρόνιο αρνητικό."}, "status": "new"}, {"id": "L01-nucleus", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The nucleus of an atom contains:", "el": "Ο πυρήνας του ατόμου περιέχει:"}, "o": [{"en": "protons and electrons", "el": "πρωτόνια και ηλεκτρόνια"}, {"en": "protons and neutrons", "el": "πρωτόνια και νετρόνια"}, {"en": "neutrons and electrons", "el": "νετρόνια και ηλεκτρόνια"}], "a": 1, "tags": ["nucleus_mixup", null, "nucleus_mixup"], "x": {"en": "Protons and neutrons form the nucleus; electrons are in shells around it.", "el": "Πρωτόνια και νετρόνια αποτελούν τον πυρήνα· τα ηλεκτρόνια είναι σε στιβάδες γύρω του."}, "status": "new"}, {"id": "L01-mass-ratio", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "A proton's mass is approximately how many times an electron's mass?", "el": "Η μάζα του πρωτονίου είναι περίπου πόσες φορές η μάζα του ηλεκτρονίου;"}, "o": [{"en": "1", "el": "1"}, {"en": "18", "el": "18"}, {"en": "1836", "el": "1836"}], "a": 2, "tags": ["electron_mass", "mass_ratio", null], "x": {"en": "m_p / m_e ≈ 1836. That is why electrons hardly count in an atom's mass.", "el": "m_p / m_e ≈ 1836. Γι' αυτό τα ηλεκτρόνια σχεδόν δεν μετράνε στη μάζα του ατόμου."}, "status": "new"}, {"id": "L01-element-protons", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "What decides which element an atom is?", "el": "Τι καθορίζει ποιο στοιχείο είναι ένα άτομο;"}, "o": [{"en": "The number of neutrons", "el": "Ο αριθμός νετρονίων"}, {"en": "The number of protons", "el": "Ο αριθμός πρωτονίων"}, {"en": "The number of electrons", "el": "Ο αριθμός ηλεκτρονίων"}], "a": 1, "tags": ["isotope_mixup", null, "ion_not_element"], "x": {"en": "The proton number (atomic number) defines the element. Changing neutrons gives an isotope; changing electrons gives an ion.", "el": "Ο αριθμός πρωτονίων (ατομικός αριθμός) ορίζει το στοιχείο. Άλλα νετρόνια δίνουν ισότοπο· άλλα ηλεκτρόνια δίνουν ιόν."}, "status": "new"}, {"id": "L01-oxygen-e", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "A neutral oxygen atom has 8 protons. How many electrons does it have?", "el": "Ουδέτερο άτομο οξυγόνου έχει 8 πρωτόνια. Πόσα ηλεκτρόνια έχει;"}, "o": [{"en": "6", "el": "6"}, {"en": "8", "el": "8"}, {"en": "16", "el": "16"}], "a": 1, "tags": ["valence_count", null, "neutral_mixup"], "x": {"en": "Neutral: electrons = protons = 8 (2 in the first shell, 6 in the second).", "el": "Ουδέτερο: ηλεκτρόνια = πρωτόνια = 8 (2 στην πρώτη στιβάδα, 6 στη δεύτερη)."}, "status": "new"}, {"id": "L01-compound", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Water (H₂O) is:", "el": "Το νερό (H₂O) είναι:"}, "o": [{"en": "an element", "el": "στοιχείο"}, {"en": "a compound", "el": "χημική ένωση"}, {"en": "an isotope", "el": "ισότοπο"}], "a": 1, "tags": ["element_mixup", null, "isotope_mixup"], "x": {"en": "Water is two elements, hydrogen and oxygen, chemically combined: a compound.", "el": "Το νερό είναι δύο στοιχεία, υδρογόνο και οξυγόνο, χημικά ενωμένα: χημική ένωση."}, "status": "new"}, {"id": "L01-molecule", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "The smallest particle of water that is still water is:", "el": "Το μικρότερο σωματίδιο νερού που είναι ακόμα νερό είναι:"}, "o": [{"en": "a hydrogen atom", "el": "ένα άτομο υδρογόνου"}, {"en": "a water molecule", "el": "ένα μόριο νερού"}, {"en": "an oxygen ion", "el": "ένα ιόν οξυγόνου"}], "a": 1, "tags": ["atom_molecule", null, "atom_molecule"], "x": {"en": "A molecule is the smallest particle that keeps the identity of the substance.", "el": "Το μόριο είναι το μικρότερο σωματίδιο που διατηρεί την ταυτότητα της ουσίας."}, "status": "new"}, {"id": "L01-shell3", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The maximum number of electrons in the third shell (n = 3) is:", "el": "Ο μέγιστος αριθμός ηλεκτρονίων στην τρίτη στιβάδα (n = 3) είναι:"}, "o": [{"en": "8", "el": "8"}, {"en": "18", "el": "18"}, {"en": "6", "el": "6"}], "a": 1, "tags": ["octet_mixup", null, "forgot_square"], "x": {"en": "2n² = 2 × 3² = 18.", "el": "2n² = 2 × 3² = 18."}, "status": "new"}, {"id": "L01-shell4", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "Using 2n², the fourth shell can hold at most:", "el": "Με τον τύπο 2n², η τέταρτη στιβάδα χωρά το πολύ:"}, "o": [{"en": "8 electrons", "el": "8 ηλεκτρόνια"}, {"en": "16 electrons", "el": "16 ηλεκτρόνια"}, {"en": "32 electrons", "el": "32 ηλεκτρόνια"}], "a": 2, "tags": ["wrong_n", "square_mixup", null], "x": {"en": "2n² = 2 × 4² = 2 × 16 = 32.", "el": "2n² = 2 × 4² = 2 × 16 = 32."}, "status": "new"}, {"id": "L01-fill-order", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "Electron shells fill:", "el": "Οι στιβάδες γεμίζουν:"}, "o": [{"en": "from the shell nearest the nucleus outwards", "el": "από τη στιβάδα πιο κοντά στον πυρήνα προς τα έξω"}, {"en": "from the outermost shell inwards", "el": "από την εξωτερική στιβάδα προς τα μέσα"}, {"en": "only after the previous shell is completely full", "el": "μόνο αφού γεμίσει εντελώς η προηγούμενη"}], "a": 0, "tags": [null, "inner_shell", "not_full"], "x": {"en": "The innermost shell has the lowest energy and fills first, but a shell need not be full before the next one starts.", "el": "Η εσωτερική στιβάδα έχει τη χαμηλότερη ενέργεια και γεμίζει πρώτη, αλλά μια στιβάδα δεν χρειάζεται να γεμίσει πριν ξεκινήσει η επόμενη."}, "status": "new"}, {"id": "L01-valence", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Valence electrons are the electrons:", "el": "Ηλεκτρόνια σθένους είναι τα ηλεκτρόνια:"}, "o": [{"en": "in the outermost shell", "el": "της εξωτερικής στιβάδας"}, {"en": "in the innermost shell", "el": "της εσωτερικής στιβάδας"}, {"en": "inside the nucleus", "el": "μέσα στον πυρήνα"}], "a": 0, "tags": [null, "inner_shell", "nucleus_mixup"], "x": {"en": "Valence electrons are in the outer shell and take part in bonding.", "el": "Τα ηλεκτρόνια σθένους είναι στην εξωτερική στιβάδα και συμμετέχουν στους δεσμούς."}, "status": "new"}, {"id": "L01-cation", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "An atom that loses an electron becomes:", "el": "Ένα άτομο που χάνει ένα ηλεκτρόνιο γίνεται:"}, "o": [{"en": "a negative ion (anion)", "el": "αρνητικό ιόν (ανιόν)"}, {"en": "a positive ion (cation)", "el": "θετικό ιόν (κατιόν)"}, {"en": "an isotope", "el": "ισότοπο"}], "a": 1, "tags": ["ion_sign", null, "isotope_mixup"], "x": {"en": "It now has more protons than electrons, so it is positive: a cation.", "el": "Έχει πλέον περισσότερα πρωτόνια από ηλεκτρόνια, άρα είναι θετικό: κατιόν."}, "status": "new"}, {"id": "L01-ion-charge", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "An atom has 11 protons and 10 electrons. It is:", "el": "Ένα άτομο έχει 11 πρωτόνια και 10 ηλεκτρόνια. Είναι:"}, "o": [{"en": "neutral", "el": "ουδέτερο"}, {"en": "a positive ion, charge +1", "el": "θετικό ιόν, φορτίο +1"}, {"en": "a negative ion, charge −1", "el": "αρνητικό ιόν, φορτίο −1"}], "a": 1, "tags": ["neutral_mixup", null, "ion_sign"], "x": {"en": "Net charge = 11 − 10 = +1 elementary charge: a cation.", "el": "Καθαρό φορτίο = 11 − 10 = +1 στοιχειώδες φορτίο: κατιόν."}, "status": "new"}, {"id": "L01-free-e", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The current in a metal wire is the flow of:", "el": "Το ρεύμα σε μεταλλικό σύρμα είναι ροή:"}, "o": [{"en": "free electrons", "el": "ελεύθερων ηλεκτρονίων"}, {"en": "protons", "el": "πρωτονίων"}, {"en": "neutrons", "el": "νετρονίων"}], "a": 0, "tags": [null, "nucleus_carrier", "neutron_mixup"], "x": {"en": "Loosely bound outer electrons drift from atom to atom; the nuclei stay in place.", "el": "Τα χαλαρά δεμένα εξωτερικά ηλεκτρόνια κινούνται από άτομο σε άτομο· οι πυρήνες μένουν στη θέση τους."}, "status": "new"}, {"id": "L01-conductor", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Which is the best conductor?", "el": "Ποιος είναι ο καλύτερος αγωγός;"}, "o": [{"en": "Silver", "el": "Άργυρος"}, {"en": "Germanium", "el": "Γερμάνιο"}, {"en": "Glass", "el": "Γυαλί"}], "a": 0, "tags": [null, "semi_mixup", "full_shell"], "x": {"en": "Silver (like copper and gold) has one loose valence electron and many free electrons.", "el": "Ο άργυρος (όπως ο χαλκός και ο χρυσός) έχει ένα χαλαρό ηλεκτρόνιο σθένους και πολλά ελεύθερα ηλεκτρόνια."}, "status": "new"}, {"id": "L01-semi", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Silicon and germanium are:", "el": "Το πυρίτιο και το γερμάνιο είναι:"}, "o": [{"en": "conductors", "el": "αγωγοί"}, {"en": "insulators", "el": "μονωτές"}, {"en": "semiconductors", "el": "ημιαγωγοί"}], "a": 2, "tags": ["semi_mixup", "semi_mixup", null], "x": {"en": "They are the common semiconductor materials used in transistors and chips.", "el": "Είναι τα συνηθισμένα υλικά ημιαγωγών, για τρανζίστορ και chips."}, "status": "new"}, {"id": "L01-breakdown", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "When a very strong electric field tears electrons loose in an insulator, this is called:", "el": "Όταν πολύ ισχυρό ηλεκτρικό πεδίο αποσπά ηλεκτρόνια σε έναν μονωτή, αυτό λέγεται:"}, "o": [{"en": "ionization of the conductor", "el": "ιονισμός του αγωγού"}, {"en": "breakdown", "el": "διάσπαση (breakdown)"}, {"en": "valence bonding", "el": "δεσμός σθένους"}], "a": 1, "tags": ["ion_breakdown", null, "inner_shell"], "x": {"en": "Breakdown: the insulator starts to conduct and is usually damaged.", "el": "Διάσπαση: ο μονωτής αρχίζει να άγει και συνήθως καταστρέφεται."}, "status": "new"}, {"id": "L02-static", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Static electricity is:", "el": "Ο στατικός ηλεκτρισμός είναι:"}, "o": [{"en": "charge at rest on the surface of an object", "el": "φορτίο σε ηρεμία στην επιφάνεια ενός σώματος"}, {"en": "charge flowing through a conductor", "el": "φορτίο που ρέει μέσα σε αγωγό"}, {"en": "a current that reverses direction", "el": "ρεύμα που αλλάζει φορά"}], "a": 0, "tags": [null, "static_dynamic", "static_dynamic"], "x": {"en": "Static: electrons at rest, piled up on a surface. Dynamic: electrons moving (DC or AC current).", "el": "Στατικός: ηλεκτρόνια σε ηρεμία, συσσωρευμένα σε επιφάνεια. Δυναμικός: ηλεκτρόνια σε κίνηση (ρεύμα DC ή AC)."}, "status": "new"}, {"id": "L02-insulator", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A static charge builds up most easily when two surfaces touch and separate and:", "el": "Στατικό φορτίο δημιουργείται πιο εύκολα όταν δύο επιφάνειες έρχονται σε επαφή και χωρίζουν και:"}, "o": [{"en": "both are copper", "el": "είναι και οι δύο από χαλκό"}, {"en": "at least one is an insulator", "el": "τουλάχιστον η μία είναι μονωτής"}, {"en": "both are grounded", "el": "είναι και οι δύο γειωμένες"}], "a": 1, "tags": ["conductor_leaks", null, "conductor_leaks"], "x": {"en": "An insulator gives the charge no path to leave, so it stays on the surface.", "el": "Ο μονωτής δεν δίνει δρόμο διαφυγής στο φορτίο, οπότε αυτό μένει στην επιφάνεια."}, "status": "new"}, {"id": "L02-tribo", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "Two materials touch. The one with weakly bound outer electrons becomes:", "el": "Δύο υλικά έρχονται σε επαφή. Αυτό με τα χαλαρά δεμένα εξωτερικά ηλεκτρόνια γίνεται:"}, "o": [{"en": "negative", "el": "αρνητικό"}, {"en": "positive", "el": "θετικό"}, {"en": "neutral", "el": "ουδέτερο"}], "a": 1, "tags": ["tribo_sign", null, "conservation"], "x": {"en": "It loses electrons to the other material, so it is left with more protons than electrons: positive.", "el": "Χάνει ηλεκτρόνια προς το άλλο υλικό, οπότε μένει με περισσότερα πρωτόνια: θετικό."}, "status": "new"}, {"id": "L02-pith-same", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Two pith balls are touched by the same charged glass rod. They will:", "el": "Δύο σφαιρίδια αγγίζονται από την ίδια φορτισμένη γυάλινη ράβδο. Θα:"}, "o": [{"en": "attract", "el": "έλκονται"}, {"en": "repel", "el": "απωθούνται"}, {"en": "not affect each other", "el": "δεν αλληλεπιδρούν"}], "a": 1, "tags": ["like_unlike", null, "charged_force"], "x": {"en": "Both get the same charge from the rod, and like charges repel.", "el": "Παίρνουν το ίδιο φορτίο από τη ράβδο, και τα όμοια φορτία απωθούνται."}, "status": "new"}, {"id": "L02-fur", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A plastic rod rubbed with fur becomes negative. The fur becomes:", "el": "Πλαστική ράβδος τριμμένη με γούνα γίνεται αρνητική. Η γούνα γίνεται:"}, "o": [{"en": "negative", "el": "αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}, {"en": "positive", "el": "θετική"}], "a": 2, "tags": ["conservation", "conservation", null], "x": {"en": "The electrons the rod gained came from the fur, so the fur is left positive. Charge is moved, not created.", "el": "Τα ηλεκτρόνια που κέρδισε η ράβδος ήρθαν από τη γούνα, οπότε η γούνα μένει θετική. Το φορτίο μετακινείται, δεν δημιουργείται."}, "status": "new"}, {"id": "L02-neutral-pull", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A charged balloon attracts a neutral piece of paper because:", "el": "Φορτισμένο μπαλόνι έλκει ουδέτερο χαρτάκι επειδή:"}, "o": [{"en": "the charges in the paper separate, and the opposite charge comes closer", "el": "τα φορτία στο χαρτί διαχωρίζονται και το αντίθετο φορτίο έρχεται πιο κοντά"}, {"en": "the paper is really positively charged", "el": "το χαρτί είναι στην πραγματικότητα θετικά φορτισμένο"}, {"en": "gravity pulls the paper up", "el": "η βαρύτητα τραβάει το χαρτί προς τα πάνω"}], "a": 0, "tags": [null, "neutral_charged", "gravity_mixup"], "x": {"en": "Polarization: the opposite charge sits on the near side, so attraction beats repulsion.", "el": "Πόλωση: το αντίθετο φορτίο βρίσκεται στην κοντινή πλευρά, οπότε η έλξη υπερισχύει της άπωσης."}, "status": "new"}, {"id": "L02-field-dir", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "The direction of an electric field line is the direction in which a small ___ test charge would move.", "el": "Η φορά μιας δυναμικής γραμμής είναι η φορά προς την οποία θα κινούνταν ένα μικρό ___ φορτίο δοκιμής."}, "o": [{"en": "positive", "el": "θετικό"}, {"en": "negative", "el": "αρνητικό"}, {"en": "neutral", "el": "ουδέτερο"}], "a": 0, "tags": [null, "test_charge", "test_charge"], "x": {"en": "By agreement a positive test charge is used, so lines point away from + and towards −.", "el": "Συμβατικά χρησιμοποιείται θετικό φορτίο δοκιμής, οπότε οι γραμμές φεύγουν από το + και πάνε προς το −."}, "status": "new"}, {"id": "L02-lines", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "Electric field lines:", "el": "Οι δυναμικές γραμμές του ηλεκτρικού πεδίου:"}, "o": [{"en": "cross where the field is strongest", "el": "τέμνονται εκεί όπου το πεδίο είναι ισχυρότερο"}, {"en": "never cross", "el": "δεν τέμνονται ποτέ"}, {"en": "form closed loops around a single charge", "el": "σχηματίζουν κλειστούς βρόχους γύρω από ένα φορτίο"}], "a": 1, "tags": ["lines_cross", null, "closed_loops"], "x": {"en": "The field has one direction at each point, so two lines can never cross. They start on + and end on −.", "el": "Το πεδίο έχει μία φορά σε κάθε σημείο, άρα δύο γραμμές δεν τέμνονται ποτέ. Ξεκινούν από + και καταλήγουν σε −."}, "status": "new"}, {"id": "L02-hollow", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "A hollow metal sphere is charged. Inside the sphere:", "el": "Κούφια μεταλλική σφαίρα φορτίζεται. Μέσα στη σφαίρα:"}, "o": [{"en": "there is no charge and no field", "el": "δεν υπάρχει φορτίο ούτε πεδίο"}, {"en": "the charge is spread over the inner surface", "el": "το φορτίο απλώνεται στην εσωτερική επιφάνεια"}, {"en": "the field is strongest at the centre", "el": "το πεδίο είναι ισχυρότερο στο κέντρο"}], "a": 0, "tags": [null, "outer_surface", "outer_surface"], "x": {"en": "Like charges push each other to the outer surface. Inside, the field is zero: a Faraday cage.", "el": "Τα όμοια φορτία σπρώχνονται στην εξωτερική επιφάνεια. Μέσα το πεδίο είναι μηδέν: κλωβός Faraday."}, "status": "new"}, {"id": "L02-points", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "On an irregularly shaped conductor, the charge is greatest:", "el": "Σε αγωγό ακανόνιστου σχήματος, το φορτίο είναι μεγαλύτερο:"}, "o": [{"en": "on the flattest areas", "el": "στις πιο επίπεδες περιοχές"}, {"en": "evenly everywhere", "el": "παντού ομοιόμορφα"}, {"en": "at the sharp points and edges", "el": "στις αιχμές και τις ακμές"}], "a": 2, "tags": ["sharp_points", "sharp_points", null], "x": {"en": "Charge piles up where the curvature is sharpest. Aircraft static wicks use sharp points to leak it away.", "el": "Το φορτίο μαζεύεται όπου η καμπυλότητα είναι εντονότερη. Τα static wicks των αεροσκαφών έχουν αιχμές γι' αυτό τον λόγο."}, "status": "new"}, {"id": "L02-esd", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Which action is most likely to cause ESD damage to a circuit card?", "el": "Ποια ενέργεια είναι πιο πιθανό να προκαλέσει ζημιά ESD σε κάρτα;"}, "o": [{"en": "Touching its connector pins", "el": "Να αγγίξεις τις ακίδες του connector"}, {"en": "Holding it while wearing a grounding wrist strap", "el": "Να την κρατάς φορώντας γειωμένο βραχιόλι"}, {"en": "Keeping it in its ESD bag", "el": "Να τη φυλάς στη σακούλα ESD"}], "a": 0, "tags": [null, "esd_safe", "esd_safe"], "x": {"en": "The charge on your body discharges through the pins into the components. Strap, bags and caps prevent this.", "el": "Το φορτίο του σώματος εκφορτίζεται μέσω των ακίδων στα εξαρτήματα. Βραχιόλι, σακούλες και καπάκια το αποτρέπουν."}, "status": "new"}, {"id": "L02-refuel", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "The aircraft and the fuel truck are bonded and grounded before refuelling because:", "el": "Το αεροσκάφος και το βυτιοφόρο γειώνονται και συνδέονται πριν τον ανεφοδιασμό επειδή:"}, "o": [{"en": "fuel is a good conductor", "el": "το καύσιμο είναι καλός αγωγός"}, {"en": "flowing fuel builds up static charge that could spark", "el": "το καύσιμο που ρέει φορτίζεται στατικά και μπορεί να προκαλέσει σπινθήρα"}, {"en": "it measures the fuel quantity", "el": "έτσι μετριέται η ποσότητα καυσίμου"}], "a": 1, "tags": ["fuel_conductor", null, "fuel_purpose"], "x": {"en": "Fuel conducts poorly, so the charge from the flow stays and a spark could ignite the vapour. Bonding equalizes the potentials.", "el": "Το καύσιμο άγει ελάχιστα, οπότε το φορτίο από τη ροή μένει και ένας σπινθήρας μπορεί να αναφλέξει τους ατμούς. Η σύνδεση εξισώνει τα δυναμικά."}, "status": "new"}, {"id": "L02-coul-d", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "The distance between two charges is doubled. The force between them becomes:", "el": "Η απόσταση δύο φορτίων διπλασιάζεται. Η δύναμη μεταξύ τους γίνεται:"}, "o": [{"en": "one half", "el": "το μισό"}, {"en": "one quarter", "el": "το ένα τέταρτο"}, {"en": "twice as large", "el": "διπλάσια"}], "a": 1, "tags": ["forgot_square_d", null, "inverse_mixup"], "x": {"en": "Force ∝ 1/d². Twice the distance → 1/2² = 1/4 of the force.", "el": "Δύναμη ∝ 1/d². Διπλάσια απόσταση → 1/2² = 1/4 της δύναμης."}, "status": "new"}, {"id": "L02-coul-q", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "One of two charges is tripled; the distance stays the same. The force:", "el": "Το ένα από δύο φορτία τριπλασιάζεται· η απόσταση μένει ίδια. Η δύναμη:"}, "o": [{"en": "triples", "el": "τριπλασιάζεται"}, {"en": "becomes 9 times larger", "el": "γίνεται 9 φορές μεγαλύτερη"}, {"en": "becomes one third", "el": "γίνεται το ένα τρίτο"}], "a": 0, "tags": [null, "square_charge", "inverse_mixup"], "x": {"en": "Force ∝ Q₁ × Q₂. Only one charge changed, by 3, so the force is ×3. Only the distance is squared.", "el": "Δύναμη ∝ Q₁ × Q₂. Άλλαξε μόνο το ένα φορτίο, ×3, άρα η δύναμη ×3. Στο τετράγωνο είναι μόνο η απόσταση."}, "status": "new"}, {"id": "L02-q-it", "lesson": "L02", "topic": "3.02", "d": 1, "units": "SI", "q": {"en": "A current of 2 A flows for 5 s. The charge that passes is:", "el": "Ρεύμα 2 A ρέει για 5 s. Το φορτίο που περνά είναι:"}, "o": [{"en": "10 C", "el": "10 C"}, {"en": "0.4 C", "el": "0,4 C"}, {"en": "2.5 C", "el": "2,5 C"}], "a": 0, "tags": [null, "inverted", "divided"], "x": {"en": "Q = I × t = 2 × 5 = 10 C.", "el": "Q = I × t = 2 × 5 = 10 C."}, "status": "new"}, {"id": "L02-electrons", "lesson": "L02", "topic": "3.02", "d": 2, "units": "SI", "q": {"en": "How many electrons make up a charge of 2 C?", "el": "Πόσα ηλεκτρόνια αντιστοιχούν σε φορτίο 2 C;"}, "o": [{"en": "6.24 × 10¹⁸", "el": "6,24 × 10¹⁸"}, {"en": "1.25 × 10¹⁹", "el": "1,25 × 10¹⁹"}, {"en": "3.12 × 10¹⁸", "el": "3,12 × 10¹⁸"}], "a": 1, "tags": ["one_coulomb", null, "divided"], "x": {"en": "1 C = 6.24 × 10¹⁸ electrons, so 2 C = 2 × 6.24 × 10¹⁸ = 1.25 × 10¹⁹.", "el": "1 C = 6,24 × 10¹⁸ ηλεκτρόνια, άρα 2 C = 2 × 6,24 × 10¹⁸ = 1,25 × 10¹⁹."}, "status": "new"}, {"id": "L02-contact", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "A positively charged rod touches a neutral metal bar. The bar becomes:", "el": "Θετικά φορτισμένη ράβδος αγγίζει ουδέτερη μεταλλική ράβδο. Η μεταλλική ράβδος γίνεται:"}, "o": [{"en": "positive", "el": "θετική"}, {"en": "negative", "el": "αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}], "a": 0, "tags": [null, "contact_induction", "conservation"], "x": {"en": "Electrons move from the bar into the rod: charging by contact gives the same sign as the rod.", "el": "Ηλεκτρόνια περνούν από τη ράβδο μετάλλου στη φορτισμένη ράβδο: η φόρτιση με επαφή δίνει το ίδιο πρόσημο."}, "status": "new"}, {"id": "L02-induction", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A metal bar is charged by induction using a positively charged rod (ground removed first, then the rod). The bar ends up:", "el": "Μεταλλική ράβδος φορτίζεται με επαγωγή από θετικά φορτισμένη ράβδο (αφαιρείται πρώτα η γείωση, μετά η ράβδος). Η μεταλλική ράβδος καταλήγει:"}, "o": [{"en": "positive", "el": "θετική"}, {"en": "negative", "el": "αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}], "a": 1, "tags": ["contact_induction", null, "ground_order"], "x": {"en": "Electrons come in from ground towards the + rod. With the ground removed first, they are trapped: negative, opposite to the rod.", "el": "Ηλεκτρόνια έρχονται από τη γείωση προς τη θετική ράβδο. Αφού αφαιρεθεί πρώτα η γείωση, εγκλωβίζονται: αρνητική, αντίθετη από τη ράβδο."}, "status": "new"}, {"id": "L02-liquid", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "In salty water, the current is carried by:", "el": "Στο αλμυρό νερό, το ρεύμα μεταφέρεται από:"}, "o": [{"en": "ions", "el": "ιόντα"}, {"en": "free electrons only", "el": "μόνο ελεύθερα ηλεκτρόνια"}, {"en": "protons leaving the nuclei", "el": "πρωτόνια που φεύγουν από τους πυρήνες"}], "a": 0, "tags": [null, "metal_liquid", "nucleus_carrier"], "x": {"en": "The dissolved salt is already split into + and − ions; they move to opposite electrodes.", "el": "Το διαλυμένο αλάτι είναι ήδη χωρισμένο σε θετικά και αρνητικά ιόντα· αυτά κινούνται προς αντίθετα ηλεκτρόδια."}, "status": "new"}, {"id": "L02-vacuum", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A vacuum can carry a current:", "el": "Το κενό μπορεί να μεταφέρει ρεύμα:"}, "o": [{"en": "always: it is an ideal conductor", "el": "πάντα: είναι ιδανικός αγωγός"}, {"en": "only if electrons are put into it, e.g. from a heated cathode", "el": "μόνο αν βάλουμε μέσα ηλεκτρόνια, π.χ. από θερμαινόμενη κάθοδο"}, {"en": "only through the ions it contains", "el": "μόνο μέσω των ιόντων που περιέχει"}], "a": 1, "tags": ["vacuum_ideal", null, "vacuum_ions"], "x": {"en": "A vacuum has no carriers of its own. Electrons put into it travel freely (vacuum tubes, X-ray tubes).", "el": "Το κενό δεν έχει δικούς του φορείς. Ηλεκτρόνια που μπαίνουν σε αυτό κινούνται ελεύθερα (λυχνίες κενού, λυχνίες ακτίνων Χ)."}, "status": "new"}, {"id": "L03-kv", "lesson": "L03", "topic": "3.03", "d": 1, "units": "SI", "q": {"en": "2.5 kV is the same as:", "el": "Τα 2,5 kV ισούνται με:"}, "o": [{"en": "25 V", "el": "25 V"}, {"en": "2 500 V", "el": "2 500 V"}, {"en": "0.0025 V", "el": "0,0025 V"}], "a": 1, "tags": ["prefix_step", null, "prefix_direction"], "x": {"en": "kilo = 1 000. Big unit → small unit: multiply. 2.5 × 1 000 = 2 500 V.", "el": "κιλό = 1 000. Από μεγάλη σε μικρή μονάδα: πολλαπλασιάζουμε. 2,5 × 1 000 = 2 500 V."}, "status": "new"}, {"id": "L03-ma", "lesson": "L03", "topic": "3.03", "d": 1, "units": "SI", "q": {"en": "0.25 A is the same as:", "el": "Τα 0,25 A ισούνται με:"}, "o": [{"en": "25 mA", "el": "25 mA"}, {"en": "2 500 mA", "el": "2 500 mA"}, {"en": "250 mA", "el": "250 mA"}], "a": 2, "tags": ["prefix_step", "prefix_step", null], "x": {"en": "A → mA: multiply by 1 000. 0.25 × 1 000 = 250 mA.", "el": "A → mA: επί 1 000. 0,25 × 1 000 = 250 mA."}, "status": "new"}, {"id": "L03-nano", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "0.047 μF is the same as:", "el": "Τα 0,047 μF ισούνται με:"}, "o": [{"en": "47 nF", "el": "47 nF"}, {"en": "4.7 nF", "el": "4,7 nF"}, {"en": "47 pF", "el": "47 pF"}], "a": 0, "tags": [null, "prefix_step", "milli_micro"], "x": {"en": "μ → n is one step of 1 000: 0.047 × 1 000 = 47 nF.", "el": "μ → n είναι ένα βήμα του 1 000: 0,047 × 1 000 = 47 nF."}, "status": "new"}, {"id": "L03-pd", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "Potential difference between two points is:", "el": "Η διαφορά δυναμικού μεταξύ δύο σημείων είναι:"}, "o": [{"en": "the work done per unit charge moved between them", "el": "το έργο ανά μονάδα φορτίου που μετακινείται μεταξύ τους"}, {"en": "the charge flowing per second", "el": "το φορτίο που ρέει ανά δευτερόλεπτο"}, {"en": "the opposition to current", "el": "η αντίσταση στη ροή ρεύματος"}], "a": 0, "tags": [null, "voltage_current", "resistance_pd"], "x": {"en": "V = W/Q: joules per coulomb. Charge per second is current; opposition is resistance.", "el": "V = W/Q: joule ανά coulomb. Φορτίο ανά δευτερόλεπτο είναι το ρεύμα· η αντίσταση στη ροή είναι η αντίσταση."}, "status": "new"}, {"id": "L03-emf", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "The electromotive force (emf) of a battery is:", "el": "Η ηλεκτρεγερτική δύναμη (ΗΕΔ) μιας μπαταρίας είναι:"}, "o": [{"en": "the voltage dropped across a lamp it feeds", "el": "η πτώση τάσης πάνω σε μια λάμπα που τροφοδοτεί"}, {"en": "the push the source gives to move charge around the circuit", "el": "η «ώθηση» που δίνει η πηγή για να κινηθεί το φορτίο στο κύκλωμα"}, {"en": "the current it delivers", "el": "το ρεύμα που δίνει"}], "a": 1, "tags": ["emf_pd", null, "voltage_current"], "x": {"en": "emf belongs to the source (energy given to the charges); a PD across a load is energy taken from them. Both in volts.", "el": "Η ΗΕΔ ανήκει στην πηγή (ενέργεια που δίνεται στα φορτία)· η τάση πάνω σε φορτίο είναι ενέργεια που αφαιρείται. Και οι δύο σε volt."}, "status": "new"}, {"id": "L03-tanks", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "In the two-tank picture (10 psi and 2 psi), what makes the water flow?", "el": "Στο παράδειγμα με τις δύο δεξαμενές (10 psi και 2 psi), τι προκαλεί τη ροή;"}, "o": [{"en": "The 8 psi difference between the tanks", "el": "Η διαφορά 8 psi μεταξύ των δεξαμενών"}, {"en": "The 10 psi in tank A", "el": "Τα 10 psi της δεξαμενής Α"}, {"en": "The size of the pipe", "el": "Το μέγεθος του σωλήνα"}], "a": 0, "tags": [null, "absolute_potential", "pipe_size"], "x": {"en": "Only a difference drives a flow: 10 − 2 = 8 psi. In a circuit, only a potential difference drives current.", "el": "Μόνο η διαφορά προκαλεί ροή: 10 − 2 = 8 psi. Σε κύκλωμα, μόνο η διαφορά δυναμικού προκαλεί ρεύμα."}, "status": "new"}, {"id": "L03-vwq", "lesson": "L03", "topic": "3.03", "d": 1, "units": "SI", "q": {"en": "120 J of energy moves 5 C of charge between two points. The potential difference is:", "el": "Ενέργεια 120 J μετακινεί φορτίο 5 C μεταξύ δύο σημείων. Η διαφορά δυναμικού είναι:"}, "o": [{"en": "24 V", "el": "24 V"}, {"en": "600 V", "el": "600 V"}, {"en": "0.042 V", "el": "0,042 V"}], "a": 0, "tags": [null, "multiplied", "inverted"], "x": {"en": "V = W / Q = 120 / 5 = 24 V.", "el": "V = W / Q = 120 / 5 = 24 V."}, "status": "new"}, {"id": "L03-wvq", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "How much energy is needed to move 3 C through a potential difference of 28 V?", "el": "Πόση ενέργεια χρειάζεται για να μετακινηθεί φορτίο 3 C μέσω διαφοράς δυναμικού 28 V;"}, "o": [{"en": "9.3 J", "el": "9,3 J"}, {"en": "84 J", "el": "84 J"}, {"en": "0.11 J", "el": "0,11 J"}], "a": 1, "tags": ["divided", null, "inverted"], "x": {"en": "W = V × Q = 28 × 3 = 84 J.", "el": "W = V × Q = 28 × 3 = 84 J."}, "status": "new"}, {"id": "L03-vpi", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "A lamp dissipates 56 W while drawing 2 A. The voltage across it is:", "el": "Λάμπα καταναλώνει 56 W με ρεύμα 2 A. Η τάση στα άκρα της είναι:"}, "o": [{"en": "112 V", "el": "112 V"}, {"en": "0.036 V", "el": "0,036 V"}, {"en": "28 V", "el": "28 V"}], "a": 2, "tags": ["multiplied", "inverted", null], "x": {"en": "From the definition of the volt: V = P / I = 56 / 2 = 28 V.", "el": "Από τον ορισμό του volt: V = P / I = 56 / 2 = 28 V."}, "status": "new"}, {"id": "L03-iqt", "lesson": "L03", "topic": "3.03", "d": 1, "units": "SI", "q": {"en": "30 C pass a point in 1 minute. The current is:", "el": "Φορτίο 30 C περνά από ένα σημείο σε 1 λεπτό. Το ρεύμα είναι:"}, "o": [{"en": "30 A", "el": "30 A"}, {"en": "0.5 A", "el": "0,5 A"}, {"en": "1 800 A", "el": "1 800 A"}], "a": 1, "tags": ["minutes", null, "multiplied"], "x": {"en": "Time in seconds: 1 min = 60 s. I = Q / t = 30 / 60 = 0.5 A.", "el": "Χρόνος σε δευτερόλεπτα: 1 min = 60 s. I = Q / t = 30 / 60 = 0,5 A."}, "status": "new"}, {"id": "L03-qit", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "A current of 5 A flows for 2 minutes. The charge that passes is:", "el": "Ρεύμα 5 A ρέει για 2 λεπτά. Το φορτίο που περνά είναι:"}, "o": [{"en": "10 C", "el": "10 C"}, {"en": "600 C", "el": "600 C"}, {"en": "2.5 C", "el": "2,5 C"}], "a": 1, "tags": ["minutes", null, "divided"], "x": {"en": "Q = I × t = 5 × 120 = 600 C (2 min = 120 s).", "el": "Q = I × t = 5 × 120 = 600 C (2 min = 120 s)."}, "status": "new"}, {"id": "L03-e-per-s", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "A current of 1 A means that every second about ___ electrons pass a point.", "el": "Ρεύμα 1 A σημαίνει ότι κάθε δευτερόλεπτο περνούν από ένα σημείο περίπου ___ ηλεκτρόνια."}, "o": [{"en": "6.24 billion (6.24 × 10⁹)", "el": "6,24 δισεκατομμύρια (6,24 × 10⁹)"}, {"en": "6.24 × 10¹⁸", "el": "6,24 × 10¹⁸"}, {"en": "1.6 × 10⁻¹⁹", "el": "1,6 × 10⁻¹⁹"}], "a": 1, "tags": ["billion_mixup", null, "elementary_charge"], "x": {"en": "1 A = 1 C/s and 1 C = 6.24 × 10¹⁸ electrons. 1.6 × 10⁻¹⁹ C is the charge of one electron.", "el": "1 A = 1 C/s και 1 C = 6,24 × 10¹⁸ ηλεκτρόνια. Το 1,6 × 10⁻¹⁹ C είναι το φορτίο ενός ηλεκτρονίου."}, "status": "new"}, {"id": "L03-drift", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "Electrons drift through a wire very slowly, yet a lamp lights the moment the switch closes, because:", "el": "Τα ηλεκτρόνια κινούνται πολύ αργά στο σύρμα, όμως η λάμπα ανάβει μόλις κλείσει ο διακόπτης, επειδή:"}, "o": [{"en": "the electrons speed up to the speed of light", "el": "τα ηλεκτρόνια επιταχύνονται στην ταχύτητα του φωτός"}, {"en": "the push travels along the whole wire almost instantly", "el": "η «ώθηση» διαδίδεται σε όλο το σύρμα σχεδόν ακαριαία"}, {"en": "the lamp stores charge in advance", "el": "η λάμπα αποθηκεύει φορτίο από πριν"}], "a": 1, "tags": ["signal_speed", null, "lamp_store"], "x": {"en": "Like a tube full of balls: push one in, one comes out at once. Every electron in the wire starts moving together.", "el": "Όπως ένας σωλήνας γεμάτος μπίλιες: σπρώχνεις μία, βγαίνει αμέσως μία στην άλλη άκρη. Όλα τα ηλεκτρόνια του σύρματος ξεκινούν μαζί."}, "status": "new"}, {"id": "L03-r-up", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "The voltage stays the same and the resistance increases. The current:", "el": "Η τάση μένει ίδια και η αντίσταση αυξάνεται. Το ρεύμα:"}, "o": [{"en": "decreases", "el": "μειώνεται"}, {"en": "increases", "el": "αυξάνεται"}, {"en": "stays the same", "el": "μένει ίδιο"}], "a": 0, "tags": [null, "ohm_inverse", "ohm_unchanged"], "x": {"en": "More opposition, less current for the same push.", "el": "Μεγαλύτερη αντίσταση, λιγότερο ρεύμα για την ίδια «ώθηση»."}, "status": "new"}, {"id": "L03-g-calc", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "24 V across a component drives 0.5 A through it. Its conductance is about:", "el": "Τάση 24 V στα άκρα ενός στοιχείου δίνει ρεύμα 0,5 A. Η αγωγιμότητά του είναι περίπου:"}, "o": [{"en": "48 S", "el": "48 S"}, {"en": "20.8 mS", "el": "20,8 mS"}, {"en": "12 S", "el": "12 S"}], "a": 1, "tags": ["G_R_mixup", null, "multiplied"], "x": {"en": "G = I / E = 0.5 / 24 = 0.0208 S = 20.8 mS. (48 is the resistance in ohms.)", "el": "G = I / E = 0,5 / 24 = 0,0208 S = 20,8 mS. (Το 48 είναι η αντίσταση σε Ω.)"}, "status": "new"}, {"id": "L03-g-quarter", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "At constant voltage, the conductance of a circuit is cut to ¼. The current becomes:", "el": "Με σταθερή τάση, η αγωγιμότητα ενός κυκλώματος γίνεται το ¼. Το ρεύμα γίνεται:"}, "o": [{"en": "¼ of its value", "el": "το ¼"}, {"en": "4 times larger", "el": "4 φορές μεγαλύτερο"}, {"en": "unchanged", "el": "ίδιο"}], "a": 0, "tags": [null, "inverse_G", "ohm_unchanged"], "x": {"en": "Current is proportional to conductance: I = G × E. G × ¼ → I × ¼.", "el": "Το ρεύμα είναι ανάλογο της αγωγιμότητας: I = G × E. G × ¼ → I × ¼."}, "status": "new"}, {"id": "L03-polarity", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "An atom with more electrons than protons has:", "el": "Άτομο με περισσότερα ηλεκτρόνια από πρωτόνια έχει:"}, "o": [{"en": "positive polarity", "el": "θετική πολικότητα"}, {"en": "negative polarity", "el": "αρνητική πολικότητα"}, {"en": "no polarity", "el": "καμία πολικότητα"}], "a": 1, "tags": ["polarity_sign", null, "neutral_mixup"], "x": {"en": "Extra electrons → negative charge → negative polarity. (Your notes, slide 17, say the opposite: that is a mistake.)", "el": "Περισσότερα ηλεκτρόνια → αρνητικό φορτίο → αρνητική πολικότητα. (Οι σημειώσεις, slide 17, λένε το αντίθετο: είναι λάθος.)"}, "status": "new"}, {"id": "L03-coulomb", "lesson": "L03", "topic": "3.03", "d": 3, "units": "SI", "q": {"en": "Two charges of 2 μC and 3 μC are 0.1 m apart in vacuum (k = 9 × 10⁹ N·m²/C²). The force between them is:", "el": "Δύο φορτία 2 μC και 3 μC απέχουν 0,1 m στο κενό (k = 9 × 10⁹ N·m²/C²). Η δύναμη μεταξύ τους είναι:"}, "o": [{"en": "0.54 N", "el": "0,54 N"}, {"en": "4.5 × 10⁶ N", "el": "4,5 × 10⁶ N"}, {"en": "5.4 N", "el": "5,4 N"}], "a": 2, "tags": ["forgot_square_d", "sum_charges", null], "x": {"en": "F = k q₁ q₂ / r² = 9 × 10⁹ × (2 × 10⁻⁶) × (3 × 10⁻⁶) / 0.1² = 0.054 / 0.01 = 5.4 N.", "el": "F = k q₁ q₂ / r² = 9 × 10⁹ × (2 × 10⁻⁶) × (3 × 10⁻⁶) / 0,1² = 0,054 / 0,01 = 5,4 N."}, "status": "new"}, {"id": "L03-conventional", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "Outside the source, conventional current is drawn flowing:", "el": "Έξω από την πηγή, η συμβατική φορά του ρεύματος σχεδιάζεται:"}, "o": [{"en": "from + to −", "el": "από + προς −"}, {"en": "from − to +", "el": "από − προς +"}, {"en": "in both directions", "el": "και προς τις δύο κατευθύνσεις"}], "a": 0, "tags": [null, "flow_direction", "flow_direction"], "x": {"en": "Conventional (Franklin): + → −. Electrons really move − → +.", "el": "Συμβατική (Franklin): + → −. Τα ηλεκτρόνια πραγματικά κινούνται − → +."}, "status": "new"}, {"id": "L03-flow-choice", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "For troubleshooting a circuit, which current direction should a technician use?", "el": "Για την αναζήτηση βλάβης σε κύκλωμα, ποια φορά ρεύματος πρέπει να χρησιμοποιεί ο τεχνικός;"}, "o": [{"en": "Only electron flow, because it is the real one", "el": "Μόνο τη φορά ηλεκτρονίων, γιατί είναι η πραγματική"}, {"en": "Only conventional flow, because textbooks use it", "el": "Μόνο τη συμβατική, γιατί τη χρησιμοποιούν τα βιβλία"}, {"en": "Either, as long as it is used consistently", "el": "Οποιαδήποτε, αρκεί να τη χρησιμοποιεί με συνέπεια"}], "a": 2, "tags": ["flow_only", "flow_only", null], "x": {"en": "Both give the same answers; mixing them in one analysis is what causes mistakes.", "el": "Και οι δύο δίνουν τα ίδια αποτελέσματα· το λάθος προκύπτει όταν τις ανακατεύεις στην ίδια ανάλυση."}, "status": "new"}]};
